def compute(vars):
    fair_value_reporting_date = vars["Fair Value on the Reporting Date"]
    fair_value_previous_date = vars["Fair Value on the Previous Reporting Date (or Initial Recognition Date)"]
    fair_value_change_gains_losses = fair_value_reporting_date - fair_value_previous_date

    return {
        "value": fair_value_change_gains_losses,
        "trace": {
            "Fair Value on the Reporting Date": fair_value_reporting_date,
            "Fair Value on the Previous Reporting Date (or Initial Recognition Date)": fair_value_previous_date,
            "output_meta": {"currency": "CNY", "scale": "million", "unit": None}
        }
    }
